PREFIX in: <http://data.world/schema/insurance/>

SELECT ?averagePolicySize
WHERE {
  {
    SELECT ((SUM(?premiumValue) / COUNT(DISTINCT ?policy)) AS ?averagePolicySize)
    WHERE {
      SERVICE <mapped> {
        ?pcd a in:PolicyCoverageDetail ;
             in:hasPolicy ?policy ;
             in:hasPremiumAmount ?premium .
        ?premium in:premiumAmount ?premiumValue .
      }
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
       (COALESCE(SUM(?lossPaymentVal), 0) AS ?totalLossPayment)
       (COALESCE(SUM(?lossReserveVal), 0) AS ?totalLossReserve)
       (COALESCE(SUM(?expensePaymentVal), 0) AS ?totalExpensePayment)
       (COALESCE(SUM(?expenseReserveVal), 0) AS ?totalExpenseReserve)
       ((COALESCE(SUM(?lossPaymentVal), 0) +
         COALESCE(SUM(?lossReserveVal), 0) +
         COALESCE(SUM(?expensePaymentVal), 0) +
         COALESCE(SUM(?expenseReserveVal), 0)) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    ?coverage in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }

    OPTIONAL {
      ?coverage in:hasPremiumAmount ?premium .
      ?premium in:premiumAmount ?premiumAmount .
    }

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentRaw .
      BIND(xsd:decimal(?lossPaymentRaw) AS ?lossPaymentVal)
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveRaw .
      BIND(xsd:decimal(?lossReserveRaw) AS ?lossReserveVal)
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentRaw .
      BIND(xsd:decimal(?expensePaymentRaw) AS ?expensePaymentVal)
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveRaw .
      BIND(xsd:decimal(?expenseReserveRaw) AS ?expenseReserveVal)
    }
  }
}
GROUP BY ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
ORDER BY ?claimNumber ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolder ?policyHolderId ?policyNumber (SUM(?amount) AS ?totalPremiumAmount)
WHERE {
  SERVICE <mapped> {
    ?policy in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }

    ?coverageDetail in:hasPolicy ?policy ;
                    in:hasPremiumAmount ?premium .

    ?premium in:premiumAmount ?amount .
  }
}
GROUP BY ?policyHolder ?policyHolderId ?policyNumber
ORDER BY ?policyNumber ?policyHolder

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmount ?catastropheName ?agentId
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasCatastrophe ?catastrophe .
      ?catastrophe in:catastropheName ?catastropheName .
    }

    OPTIONAL {
      ?claim in:against ?coverage .
      ?coverage a in:PolicyCoverageDetail ;
                in:hasPolicy ?policy .
      ?policy in:policyNumber ?policyNumber ;
              in:hasPolicyHolder ?policyHolderRes .
      OPTIONAL { ?policy in:soldByAgent ?agent . ?agent in:agentId ?agentId . }
      OPTIONAL {
        ?coverage in:hasPremiumAmount ?premium .
        ?premium in:premiumAmount ?premiumAmount .
      }
      OPTIONAL { ?policyHolderRes in:policyHolderId ?policyHolder . }
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent in:agentId ?agentId .

    ?coverage in:hasPolicy ?policy .

    ?claim in:against ?coverage ;
           in:claimNumber ?claimNumber ;
           in:hasExpenseReserve ?expenseReserve .

    ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber
